import React from "react";
import styles from "./Project.module.css";
import axios from "axios";
function Project() {
    const [project, setProject] = useState(null)

    useEffect(() => {
        axios.get("http://localhost:3001/project-info")
            .then((response) => setProject(response.data[0])) // Access the first element of the array
            .catch((error) => console.error("Error fetching project info", error));

    }, []);

    return (

        <div className={styles.Description_p1}>
            <h3 className={styles.Project_title}>{project.name}</h3>
            <h4 className={styles.Project_text}>{project.description}</h4>
            <h3 className={styles.Project_tech}>{project.technology}</h3>
        </div>

    )
}
export default Project;
